# app/api/setup.py
# Token-gated initial setup (setup wizard).
#
# The SETUP_TOKEN is generated by the installer and written to
# /var/lib/pastegate/SETUP_TOKEN (systemd StateDirectory, owned by the service).
# Setup mode is open while this (non-empty) file exists AND setup_state is not completed:
#   - GET  /status        reports needs_setup + has_admin
#   - POST /verify-token  checks the token in constant time
#   - POST /create-admin  creates the first admin (only if no admin exists yet)
#   - POST /init-totp     creates a TOTP secret for the admin (QR via otpauth URI)
#   - POST /confirm-totp  enables 2FA
#   - POST /init-apikey   creates the first API key (cleartext returned ONCE)
#   - POST /settings      sets organisation-wide settings (default_lang)
#   - POST /complete      marks setup as completed in the DB, then removes the token
#
# Lock: once setup_state.completed is true, every endpoint here answers 403 —
# even with a valid token. The DB flag is authoritative; deleting the token file
# is only cleanup. It is set by /complete or by the first admin login (any login
# path), so an abandoned wizard does not leave the token usable. Installations
# without a setup_state row that already have an admin (never migrated) count
# as completed. init-totp/confirm-totp never touch an already active 2FA (409).
# POST requests are rate-limited per IP like the login (app/main.py).
#
# Reuses the existing auth/key/TOTP helpers. State: setup_state (migration 0010).

import hmac
import logging
import os
from datetime import datetime, timezone

import pyotp
from fastapi import APIRouter, Depends, HTTPException, status
from pydantic import BaseModel, Field
from sqlalchemy import func, inspect, select
from sqlalchemy.dialects.postgresql import insert as pg_insert
from sqlalchemy.exc import SQLAlchemyError
from sqlalchemy.orm import Session

from app.core.app_settings import set_default_lang
from app.core.database import get_db
from app.core.i18n import LANG_PATTERN, _
from app.core.qr import totp_qr_data_uri
from app.core.security import generate_api_key, hash_api_key, hash_password
from app.models.models import ApiKey, SetupState, User, UserRole

router = APIRouter(prefix='/api/v1/setup', tags=['setup'])
log = logging.getLogger(__name__)

# Token file location (native: StateDirectory, container: bind-mounted dir) –
# overridable via env.
_TOKEN_CANDIDATES = [
    os.environ.get('SETUP_TOKEN_PATH', ''),
    '/var/lib/pastegate/SETUP_TOKEN',
]


def _token_path() -> str | None:
    for p in _TOKEN_CANDIDATES:
        if p and os.path.isfile(p):
            return p
    return None


def _read_token() -> str | None:
    p = _token_path()
    if not p:
        return None
    try:
        with open(p, 'r', encoding='utf-8') as f:
            return f.read().strip()
    except OSError:
        return None


def _token_present() -> bool:
    return bool(_read_token())


def _clear_token() -> bool:
    """Make the token unusable, best-effort: delete it first, otherwise empty it.
    Returns True if the token is gone/empty afterwards, else False."""
    p = _token_path()
    if not p:
        return True
    try:
        os.remove(p)
        return True
    except OSError:
        pass
    try:
        with open(p, 'w', encoding='utf-8') as f:
            f.write('')
        return True
    except OSError:
        return False


def _active_admin(db: Session) -> User | None:
    return db.scalar(
        select(User).where(User.role == UserRole.admin, User.is_active == True)  # noqa: E712
        .order_by(User.created_at)
    )


def _admin_exists(db: Session) -> bool:
    """True as soon as an admin has EVER been created (active or deactivated).
    Guard against setup reactivation: if the only admin is later deactivated
    and the token file was not deleted, /setup must NOT be able to create
    another admin."""
    return db.scalar(
        select(User).where(User.role == UserRole.admin).limit(1)
    ) is not None


def _setup_completed(db: Session) -> bool:
    """Authoritative lock. Without a setup_state row – or without the table,
    if migration 0010 has not run yet – an existing admin means the installation
    predates the flag and is treated as completed."""
    if not inspect(db.connection()).has_table(SetupState.__tablename__):
        return _admin_exists(db)
    state = db.get(SetupState, 1)
    if state is not None:
        return state.completed
    return _admin_exists(db)


def _setup_open(db: Session) -> bool:
    return not _setup_completed(db) and _token_present()


def _mark_completed(db: Session) -> None:
    """Upsert of row 1: concurrent admin logins must not collide on the insert."""
    stmt = (
        pg_insert(SetupState)
        .values(id=1, completed=True, completed_at=func.now())
        .on_conflict_do_update(
            index_elements=[SetupState.id],
            set_={'completed': True,
                  'completed_at': func.coalesce(SetupState.completed_at, func.now())},
            where=SetupState.completed.is_(False),
        )
    )
    db.execute(stmt)


def complete_on_admin_login(db: Session, user: User) -> None:
    """Setup is no longer needed once an admin has logged in: lock it, even if
    the wizard was abandoned before /complete. Called by every login path, in
    the login's transaction (the caller commits); the token file is removed
    afterwards, best-effort.

    Never blocks the login: a failure is logged and the login goes on. Without a
    setup_state row (or table) the admin-exists fallback locks setup anyway; an
    abandoned wizard (row with completed=false) then stays as it was until the
    next admin login."""
    if user.role != UserRole.admin:
        return
    try:
        with db.begin_nested():   # savepoint: an error must not abort the login transaction
            if not inspect(db.connection()).has_table(SetupState.__tablename__):
                return  # migration 0010 pending – the admin-exists fallback locks setup
            _mark_completed(db)
    except SQLAlchemyError:
        log.warning('could not lock setup on admin login – login continues',
                    exc_info=True, extra={'event': 'setup_lock_on_login_failed'})


def clear_token_after_login(db: Session) -> None:
    """Remove the token file once setup is locked (after the login's commit).
    While setup is still open – e.g. a viewer logged in – the token stays."""
    try:
        if not _token_present() or not _setup_completed(db):
            return
    except SQLAlchemyError:
        log.warning('setup state could not be read after login', exc_info=True)
        return   # the login is already committed; never turn it into a 500
    if not _clear_token():
        log.warning('setup is locked, but the token file could not be removed: %s', _token_path())


def _require_token(provided: str, db: Session) -> None:
    """Setup-open check + constant-time comparison. Raises 403/401 on failure."""
    if not _setup_open(db):
        raise HTTPException(status_code=status.HTTP_403_FORBIDDEN, detail=_('setup.already_completed'))
    real = _read_token() or ''
    if not provided or not hmac.compare_digest(provided, real):
        raise HTTPException(status_code=status.HTTP_401_UNAUTHORIZED, detail=_('setup.invalid_token'))


# ── Schemas ───────────────────────────────────────────────────────

class TokenBody(BaseModel):
    token: str = Field(min_length=1, max_length=256)


class CreateAdminBody(TokenBody):
    username: str = Field(min_length=2, max_length=64)
    email:    str = Field(min_length=3, max_length=256)
    password: str = Field(min_length=12, max_length=256)


class ConfirmTotpBody(TokenBody):
    totp_code: str = Field(min_length=6, max_length=6)


class InitApiKeyBody(TokenBody):
    name: str = Field(default='Extension – Rollout', min_length=1, max_length=128)


class SettingsBody(TokenBody):
    default_lang: str = Field(pattern=LANG_PATTERN)


# ── Endpoints ─────────────────────────────────────────────────────

@router.get('/status')
def status_(db: Session = Depends(get_db)):
    """Public. Drives the frontend gate (/setup redirect).
    needs_setup is only true while setup is open AND there is no admin yet."""
    has_admin = _admin_exists(db)
    return {
        'needs_setup': _setup_open(db) and not has_admin,
        'has_admin':   has_admin,
    }


@router.post('/verify-token')
def verify_token(body: TokenBody, db: Session = Depends(get_db)):
    _require_token(body.token, db)
    return {'valid': True, 'has_admin': _active_admin(db) is not None}


@router.post('/create-admin', status_code=status.HTTP_201_CREATED)
def create_admin(body: CreateAdminBody, db: Session = Depends(get_db)):
    _require_token(body.token, db)
    if _admin_exists(db):
        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail=_('setup.admin_exists'))
    if db.scalar(select(User).where(User.username == body.username)):
        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail=_('users.username_taken'))

    user = User(
        username=body.username,
        email=body.email,
        password_hash=hash_password(body.password),
        role=UserRole.admin,
        is_active=True,
    )
    db.add(user)
    # Create the state row in the same transaction: from now on the lock
    # depends only on the flag, not on the admin-exists fallback.
    if db.get(SetupState, 1) is None:
        db.add(SetupState(id=1, completed=False))
    db.commit()
    return {'id': str(user.id), 'username': user.username, 'role': user.role.value}


@router.post('/init-totp')
def init_totp(body: TokenBody, db: Session = Depends(get_db)):
    """Create a TOTP secret for the admin. The frontend renders the QR code from qr_uri."""
    _require_token(body.token, db)
    admin = _active_admin(db)
    if not admin:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=_('setup.no_admin'))
    if admin.totp_enabled:
        # Never replace an active second factor through the setup token
        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail=_('setup.totp_already_enabled'))
    secret = pyotp.random_base32()
    qr_uri = pyotp.TOTP(secret).provisioning_uri(name=admin.email, issuer_name='Pastegate')
    admin.totp_secret  = secret
    admin.totp_enabled = False
    db.commit()
    return {'secret': secret, 'qr_uri': qr_uri, 'qr_image': totp_qr_data_uri(qr_uri)}


@router.post('/confirm-totp')
def confirm_totp(body: ConfirmTotpBody, db: Session = Depends(get_db)):
    _require_token(body.token, db)
    admin = _active_admin(db)
    if not admin or not admin.totp_secret:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=_('auth.totp_no_secret'))
    if admin.totp_enabled:
        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail=_('setup.totp_already_enabled'))
    if not pyotp.TOTP(admin.totp_secret).verify(body.totp_code, valid_window=1):
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=_('auth.totp_invalid'))
    admin.totp_enabled = True
    db.commit()
    return {'totp_enabled': True}


@router.post('/init-apikey', status_code=status.HTTP_201_CREATED)
def init_apikey(body: InitApiKeyBody, db: Session = Depends(get_db)):
    """Create the first API key. The cleartext is returned ONCE (DB: HMAC hash only)."""
    _require_token(body.token, db)
    admin = _active_admin(db)
    if not admin:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=_('setup.no_admin'))
    raw = generate_api_key()
    db.add(ApiKey(user_id=admin.id, name=body.name, key_hash=hash_api_key(raw), is_active=True))
    db.commit()
    return {'key': raw}


@router.post('/settings')
def save_settings(body: SettingsBody, db: Session = Depends(get_db)):
    _require_token(body.token, db)
    set_default_lang(db, body.default_lang)
    db.commit()
    return {'default_lang': body.default_lang}


@router.post('/complete')
def complete(body: TokenBody, db: Session = Depends(get_db)):
    """Finish setup. The DB flag is committed first; if that fails, the request
    fails (no 200). Removing the token file afterwards is cleanup only — the
    flag already locks every setup endpoint."""
    _require_token(body.token, db)
    if _active_admin(db) is None:
        raise HTTPException(status_code=status.HTTP_400_BAD_REQUEST, detail=_('setup.cannot_complete'))
    state = db.get(SetupState, 1) or SetupState(id=1)
    state.completed = True
    state.completed_at = datetime.now(timezone.utc)
    db.add(state)
    db.commit()
    cleared = _clear_token()
    if not cleared:
        log.warning('setup completed, but the token file could not be removed: %s', _token_path())
    return {'ok': True, 'token_cleared': cleared}
